        while c < w:
            if a[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and a[r][c] != 0:
                c += 1
            seq = a[r][start:c]
            if len(seq) >= 2:
                endrow = r + 1
                while endrow < h and a[endrow][start:c] == seq:
                    endrow += 1
                if endrow - r >= 2:
                    palette = (r, endrow, start, c, seq)
                    break
        if palette:
            break
    if palette is None:
        raise ValueError('repeated palette not found')
    pr0, pr1, pc0, pc1, seq = palette

    # Extract the motif belonging to the palette's middle color (the 1 layer
    # in these tasks), excluding the palette itself.
    target_color = 1
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if a[r][c] != target_color or (r, c) in seen or pr0 <= r < pr1 and pc0 <= c < pc1:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and a[ny][nx] == target_color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            components.append(comp)
    if not components:
        raise ValueError('motif not found')
    motif = max(components, key=len)
    top = min(y for y, x in motif)
    left = min(x for y, x in motif)
    rel = [(y-top, x-left) for y, x in motif]
    mh = max(y for y, x in rel) + 1
    # Locate the existing 1-colored layer in the palette sequence.
    idx = seq.index(target_color)
    first_top = top - idx * mh
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        band_top = first_top + i * mh
        for dy, dx in rel:
            y, x = band_top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

